INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES
(240, 0, 'itIT', 'Ah, è già abbastanza difficile mantenere l''ordine, anche senza che spuntino in continuazione nuovi problemi! Spero che tu porti buone notizie, $n...', 0),
(2817, 0, 'itIT', 'Devi essere forte per vagare per le Maleterre, $C. Come me.$B$BO forse sei qui perché sei $gpazzo:pazza;. Come me.', 0),
(3339, 0, 'itIT', 'Spero che sia importante.', 0),
(3391, 0, 'itIT', 'Thrall paga bene me e i miei ragazzi per dare una mano nella costruzione di Orgrimmar, quindi ho deciso di stabilirmi qui. $b$bFacciamo gran parte degli affari con la Baia del Bottino e il Barone Granbottino.', 0),
(5598, 0, 'itIT', 'Cosa vuoi da me?', 0),
(8379, 0, 'itIT', 'Se sei qui per implorare di concederti il privilegio di lavorare per me, allora sei $gil benvenuto:la benvenuta;. Altrimenti, dubito che potresti essermi utile in qualche modo.', 0),
(9081, 0, 'itIT', 'Non manco mai il bersaglio!', 0),
(11039, 0, 'itIT', 'Salute, $n. Sono il Duca Nicholas Zverenhoff dell''Alba d''Argento.', 0);
